        /// <summary>查当前语言下的文字；查不到就退回中文；中文也没有就返回 key 本身兜底。</summary>
        public static string T(string key) {
            string[] pair;
            if (!Table.TryGetValue(key, out pair)) return key;
            int idx = CurrentLanguage == En ? 1 : 0;
            return (idx < pair.Length && !string.IsNullOrEmpty(pair[idx])) ? pair[idx] : pair[0];
        }

        /// <summary>2026-09-30 固定取英文译文，不看 CurrentLanguage —— 给"文件是哪个语言导出的
        /// 都要认得出来"这类往返一致性场景用(比如 HeatExcelService 导入Excel时，表头不管是
        /// 中文还是English模式导出的都要匹配上)。缺key就返回key本身，同 T() 的安全网原则。</summary>
        public static string TEnglish(string key) {
            string[] pair;
            if (!Table.TryGetValue(key, out pair)) return key;
            return (pair.Length > 1 && !string.IsNullOrEmpty(pair[1])) ? pair[1] : pair[0];
        }

        /// <summary>2026-09-30 固定取中文原文，不看 CurrentLanguage —— TEnglish() 的对称版本，
        /// 给"CSV/Excel 表头中英文都要认得出来"这类往返一致性场景配对使用。</summary>
        public static string TChinese(string key) {
            string[] pair;
            if (!Table.TryGetValue(key, out pair)) return key;
            return pair[0];
        }

        /// <summary>2026-09-21【第七阶段: MessageBox 弹窗】T() 只管"整句话固定不变"的文字；
        /// 弹窗消息大多是 string.Format 拼出来的("确定删除 {0} 吗?")，这里把查表结果当
        /// format 模板用。中英文模板里的 {0}/{1}… 占位符个数/顺序必须跟调用处传的参数对上，
        /// 对不上会被 catch 住退回原模板文字(带着没换掉的{0})而不是崩溃。</summary>
        public static string F(string key, params object[] args) {
            try { return string.Format(T(key), args); } catch { return T(key); }
        }

        public static void LoadSaved() {
            try {
                if (File.Exists(LanguagePath)) {
                    var j = JObject.Parse(File.ReadAllText(LanguagePath, Encoding.UTF8));
                    string lang = j["Language"] != null ? j["Language"].ToString() : "";
                    if (lang == En) CurrentLanguage = En;
                }
            } catch { }
        }

        private static void Save() {
            try {
                var j = new JObject();
                j["Language"] = CurrentLanguage;
                File.WriteAllText(LanguagePath, j.ToString(Newtonsoft.Json.Formatting.Indented), new UTF8Encoding(false));
            } catch { }
        }

        /// <summary>把当前语言下的每一条文字写进 Application.Resources —— DynamicResource 绑定会跟着活刷新。</summary>
        public static void Apply() {
            var app = Application.Current;
            if (app == null) return;
            foreach (var kv in Table) {
                app.Resources[kv.Key] = T(kv.Key);
            }
        }

        /// <summary>纯展示用的赛次名翻译——"预赛"/"半决赛"/"决赛"这几个值本身在别处是拿来
        /// 做比较/存档的数据哨兵(不能翻译，见 384d37d 起的说明)，这个函数只用在拼接给人看
        /// 的标题/列头文字时，不改变调用方手里那份 stage 字符串本身。</summary>
        public static string StageDisplay(string zhStage) {
            switch (zhStage) {
                case "预赛": return T("Str_Stage_Prelim");
                case "半决赛": return T("Str_Stage_Semi");
                case "决赛": return T("Str_Stage_Final");
                default: return zhStage ?? "";
            }
        }

        /// <summary>纯展示用的性别翻译——同 StageDisplay 的道理, "男"/"女"/"混合"本身在别处
        /// 是比较/存档用的数据哨兵，这个函数只用于拼接给人看的文字，不改变调用方手里的原值。</summary>
        public static string GenderDisplay(string zhGender) {
            switch (zhGender) {
                case "男": return T("Str_Gender_Male");
                case "女": return T("Str_Gender_Female");
                case "混合": return T("Str_Gender_Mixed");
                default: return zhGender ?? "";
            }
        }

        /// <summary>2026-09-30 StaffGroups.* 五个组名是数据哨兵(StaffMember.Group 存的就是这几个
        /// 中文字面量，全系统靠 == 比较)，跟 Gender/Stage 一样只在展示层包一层，源数据不翻译。
        /// 目前只接入了"导出花名册"(sheet 名/标题)，StaffManageWindow 主界面表格/筛选下拉还是
        /// 原样中文——那是更大的一块(整窗口重绑), 未跟这次一起改。</summary>
        public static string StaffGroupDisplay(string zhGroup) {
            switch (zhGroup) {
                case "主席团": return T("Str_StaffGroup_Presidium");
                case "组织委员会": return T("Str_StaffGroup_OrgCommittee");
                case "工作机构": return T("Str_StaffGroup_WorkOrg");
                case "技术及仲裁": return T("Str_StaffGroup_TechArbitration");
                case "裁判员": return T("Str_StaffGroup_Referees");
                default: return zhGroup ?? "";
            }
        }

        /// <summary>2026-09-28【跨客户端语言同步】远程收到主服务器权威语言状态后原样应用——
        /// 跟 Toggle() 的区别: Toggle 是"翻转"(本机操作员点按钮), 这个是"设成指定值"(收到
        /// LANGUAGE_SYNC 推送)。值跟当前一致时直接跳过、不重复 Save/Apply, 调用方可用返回值
        /// 判断要不要接着跑那串"重刷UI"级联(没变化就没必要白跑一次)。</summary>
        public static bool SetLanguage(string lang) {
            string normalized = (lang == En) ? En : Zh;
            if (normalized == CurrentLanguage) return false;
            CurrentLanguage = normalized;
            Save();
            Apply();
            return true;
        }

        public static void Toggle() {
            CurrentLanguage = CurrentLanguage == En ? Zh : En;
            Save();
            Apply();
        }
    }
